```java
public static int countDoubles(String s) {
    int count = 0;
    for (int i = 0; i < s.length() - 1; i++) {
        if (s.substring(i, i + 1).equals(s.substring(i + 1, i + 2))) {
            count++;
        }
    }
    return count;
}
```

```java
public static int longestRun(String s) {
    int best = 1;
    int cur = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            cur++;
        } else {
            cur = 1;
        }
        if (cur > best) {
            best = cur;
        }
    }
    return best;
}
```

```java
public class PunchCard {
    private int remaining;
    private int punches;
    public PunchCard(int visits) {
        remaining = visits;
        punches = 0;
    }
    public boolean punch() {
        if (remaining == 0) {
            return false;
        }
        remaining--;
        punches++;
        if (punches % 3 == 0) {
            remaining++;
        }
        return true;
    }
    public int getRemaining() {
        return remaining;
    }
}
```

```java
public int totalTime(String artist) {
    int total = 0;
    for (Song s : songs) {
        if (s.getArtist().equals(artist)) {
            total += s.getSeconds();
        }
    }
    return total;
}
```

```java
public int removeShort(int min) {
    int removed = 0;
    for (int i = songs.size() - 1; i >= 0; i--) {
        if (songs.get(i).getSeconds() < min) {
            songs.remove(i);
            removed++;
        }
    }
    return removed;
}
```

```java
public int emptyInRow(int row) {
    int count = 0;
    for (int c = 0; c < seats[row].length; c++) {
        if (seats[row][c] == 0) {
            count++;
        }
    }
    return count;
}
```

```java
public int findBlock(int k) {
    for (int r = 0; r < seats.length; r++) {
        int run = 0;
        for (int c = 0; c < seats[r].length; c++) {
            if (seats[r][c] == 0) {
                run++;
            } else {
                run = 0;
            }
            if (run >= k) {
                return r;
            }
        }
    }
    return -1;
}
```
